import math
import torch
import torch.nn as nn
import torch.nn.init as init
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.extern .shared .align 4 .b8 sdata[];
.visible .entry conv3d_ncdhw(
    .param .u64 x_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 y_ptr,
    .param .u32 N,
    .param .u32 Cin,
    .param .u32 Cout,
    .param .u32 D,
    .param .u32 H,
    .param .u32 W,
    .param .u32 K,
    .param .u32 P,
    .param .u32 Dout,
    .param .u32 Hout,
    .param .u32 Wout,
    .param .u32 has_bias
)
{
    .reg .pred p0, p1, p2, p3, p4, p5, p6;
    .reg .pred px0, px1, px_ok, py0, py1, py_ok, pz0, pz1, pz_ok, p_yz_ok, pbias0, pstore;
    .reg .b64 xbase, wbase, bbase, ybase;
    .reg .b64 addr_x, addr_w, addr_b, addr_y;
    .reg .b64 smem_base, w_sh_ptr, x_sh_ptr, addr_s, addr_s2, addr_s3, addr_s4, addr_sw, addr_sx;
    .reg .u32 rN, rCin, rCout, rD, rH, rW, rK, rP, rDout, rHout, rWout, rHasBias;
    .reg .u32 r_tid, r_bdim, r_bx, r_by, r_bz;
    .reg .u32 r_wout_start, r_wout;
    .reg .u32 r_t, r_tmp1, r_tmp2, r_tmp3;
    .reg .u32 r_n, r_oc, r_dout, r_hout;
    .reg .u32 r_ic, r_kz, r_ky, r_kx;
    .reg .u32 r_base_w, r_w_idx;
    .reg .u32 r_base0, r_x_idx, ru_sx, ru_sy, ru_sz;
    .reg .u32 r_tx, r_stripe_len;
    .reg .s32 sP, s_wout_start, s_x_base, s_hout, s_dout, s_y_base, s_z_base, s_z, s_y, s_xi;
    .reg .f32 acc, xval, wval, xval2, wval2, bval;
    // Load pointers
    ld.param.u64 xbase, [x_ptr];
    ld.param.u64 wbase, [w_ptr];
    ld.param.u64 bbase, [b_ptr];
    ld.param.u64 ybase, [y_ptr];
    // Load sizes
    ld.param.u32 rN, [N];
    ld.param.u32 rCin, [Cin];
    ld.param.u32 rCout, [Cout];
    ld.param.u32 rD, [D];
    ld.param.u32 rH, [H];
    ld.param.u32 rW, [W];
    ld.param.u32 rK, [K];
    ld.param.u32 rP, [P];
    ld.param.u32 rDout, [Dout];
    ld.param.u32 rHout, [Hout];
    ld.param.u32 rWout, [Wout];
    ld.param.u32 rHasBias, [has_bias];
    // Thread/block indices
    mov.u32 r_tid, %tid.x;
    mov.u32 r_bdim, %ntid.x;
    mov.u32 r_bx, %ctaid.x;
    mov.u32 r_by, %ctaid.y;
     mov.u32 r_bz, %ctaid.z;
    // Compute output w start and thread's w index
    mul.lo.u32 r_wout_start, r_bx, r_bdim;
    add.u32 r_wout, r_wout_start, r_tid;
    // Decode blockIdx.y into (n, oc, dout, hout)
     mov.u32 r_hout, r_bz;
     mov.u32 r_t, r_by;
     rem.u32 r_dout, r_t, rDout;
     div.u32 r_t, r_t, rDout;
     rem.u32 r_oc, r_t, rCout;
     div.u32 r_n, r_t, rCout;
    // Base offsets for y and z considering padding
    cvt.s32.u32 s_hout, r_hout;
    cvt.s32.u32 s_dout, r_dout;
    cvt.s32.u32 sP, rP;
    sub.s32 s_y_base, s_hout, sP;
    sub.s32 s_z_base, s_dout, sP;
    // Base x (stripe) start considering padding
    cvt.s32.u32 s_wout_start, r_wout_start;
    sub.s32 s_x_base, s_wout_start, sP;
    // Shared memory base pointers
    mov.u64 smem_base, sdata;
    // w_sh at offset 0, x_sh after K floats
    mul.wide.u32 addr_s, rK, 4;
    mov.u64 w_sh_ptr, smem_base;
    add.u64 x_sh_ptr, smem_base, addr_s;
    // stripe_len = blockDim.x + K - 1
    mov.u32 r_stripe_len, r_bdim;
    add.u32 r_tmp1, rK, 0xffffffff; // K-1
    add.u32 r_stripe_len, r_stripe_len, r_tmp1;
    // Initialize accumulator
    mov.f32 acc, 0f00000000;
    // Loop over input channels and kernel
    mov.u32 r_ic, 0;
IC_LOOP:
    setp.ge.u32 p0, r_ic, rCin;
    @p0 bra END_IC;
    mov.u32 r_kz, 0;
KZ_LOOP:
    setp.ge.u32 p1, r_kz, rK;
    @p1 bra END_KZ;
    // z coordinate and predicate
    cvt.s32.u32 s_y, r_kz; // reuse s_y as temp for skz
    add.s32 s_z, s_z_base, s_y; // s_y holds skz
    setp.ge.s32 pz0, s_z, 0;
    setp.lt.s32 pz1, s_z, rD;
    and.pred pz_ok, pz0, pz1;
    mov.u32 r_ky, 0;
KY_LOOP:
    setp.ge.u32 p2, r_ky, rK;
    @p2 bra END_KY;
    // y coordinate and predicate
    cvt.s32.u32 s_y, r_ky;
    add.s32 s_y, s_y_base, s_y;
    setp.ge.s32 py0, s_y, 0;
    setp.lt.s32 py1, s_y, rH;
    and.pred py_ok, py0, py1;
    and.pred p_yz_ok, pz_ok, py_ok;
    // Compute base weight index: (((((oc*Cin + ic)*K + kz)*K + ky)*K))
    mul.lo.u32 r_tmp1, r_oc, rCin;
    add.u32    r_tmp1, r_tmp1, r_ic;
    mul.lo.u32 r_tmp1, r_tmp1, rK;
    add.u32    r_tmp1, r_tmp1, r_kz;
    mul.lo.u32 r_tmp1, r_tmp1, rK;
    add.u32    r_tmp1, r_tmp1, r_ky;
    mul.lo.u32 r_base_w, r_tmp1, rK;
    // Load weights cooperatively into shared memory
    mov.u32 r_t, r_tid;
W_LOAD_LOOP:
    setp.ge.u32 p3, r_t, rK;
    @p3 bra W_LOAD_DONE;
    add.u32 r_w_idx, r_base_w, r_t;
    cvt.u64.u32 addr_w, r_w_idx;
    shl.b64     addr_w, addr_w, 2;
    add.u64     addr_w, addr_w, wbase;
    ld.global.f32 wval, [addr_w];
    mul.wide.u32 addr_s, r_t, 4;
    add.u64     addr_s, w_sh_ptr, addr_s;
    st.shared.f32 [addr_s], wval;
    add.u32 r_t, r_t, r_bdim;
    bra W_LOAD_LOOP;
W_LOAD_DONE:
    // Prepare and load x stripe into shared memory
    @p_yz_ok bra LOAD_X_STRIPE;
    // Not in bounds for y or z: fill stripe with zeros
    mov.u32 r_t, r_tid;
FILL_ZERO_LOOP:
    setp.ge.u32 p4, r_t, r_stripe_len;
    @p4 bra FILL_ZERO_DONE;
    mul.wide.u32 addr_s2, r_t, 4;
    add.u64     addr_s2, x_sh_ptr, addr_s2;
    st.shared.f32 [addr_s2], 0f00000000;
    add.u32 r_t, r_t, r_bdim;
    bra FILL_ZERO_LOOP;
FILL_ZERO_DONE:
    // Sync before using shared memory
    bar.sync 0;
    bra AFTER_X_LOAD;
LOAD_X_STRIPE:
    // Convert z and y to unsigned for indexing
    cvt.u32.s32 ru_sz, s_z;
    cvt.u32.s32 ru_sy, s_y;
    // base0 = (((n*Cin + ic)*D + z)*H + y) * W
    mul.lo.u32 r_tmp2, r_n, rCin;
    add.u32    r_tmp2, r_tmp2, r_ic;
    mul.lo.u32 r_tmp2, r_tmp2, rD;
    add.u32    r_tmp2, r_tmp2, ru_sz;
    mul.lo.u32 r_tmp2, r_tmp2, rH;
    add.u32    r_tmp2, r_tmp2, ru_sy;
    mul.lo.u32 r_base0, r_tmp2, rW;
    // Cooperative load of stripe_len elements
    mov.u32 r_t, r_tid;
X_LOAD_LOOP:
    setp.ge.u32 p5, r_t, r_stripe_len;
    @p5 bra X_LOAD_DONE;
    // x_i = s_x_base + r_t
    add.s32 s_xi, s_x_base, r_t;
    setp.ge.s32 px0, s_xi, 0;
    setp.lt.s32 px1, s_xi, rW;
    and.pred px_ok, px0, px1;
    @!px_ok bra X_STORE_ZERO;
    cvt.u32.s32 ru_sx, s_xi;
    add.u32    r_x_idx, r_base0, ru_sx;
    cvt.u64.u32 addr_x, r_x_idx;
    shl.b64     addr_x, addr_x, 2;
    add.u64     addr_x, addr_x, xbase;
    ld.global.f32 xval, [addr_x];
    mul.wide.u32 addr_s3, r_t, 4;
    add.u64     addr_s3, x_sh_ptr, addr_s3;
    st.shared.f32 [addr_s3], xval;
    bra X_STORE_DONE;
X_STORE_ZERO:
    mul.wide.u32 addr_s4, r_t, 4;
    add.u64     addr_s4, x_sh_ptr, addr_s4;
    st.shared.f32 [addr_s4], 0f00000000;
X_STORE_DONE:
    add.u32 r_t, r_t, r_bdim;
    bra X_LOAD_LOOP;
X_LOAD_DONE:
    // Sync before using shared memory
    bar.sync 0;
AFTER_X_LOAD:
    // Accumulate using shared weights and x stripe
    mov.u32 r_kx, 0;
KX_INNER:
    setp.ge.u32 p6, r_kx, rK;
    @p6 bra KX_DONE;
    mul.wide.u32 addr_sw, r_kx, 4;
    add.u64     addr_sw, w_sh_ptr, addr_sw;
    ld.shared.f32 wval2, [addr_sw];
    add.u32 r_tx, r_tid, r_kx;
    mul.wide.u32 addr_sx, r_tx, 4;
    add.u64     addr_sx, x_sh_ptr, addr_sx;
    ld.shared.f32 xval2, [addr_sx];
    fma.rn.f32 acc, xval2, wval2, acc;
    add.u32 r_kx, r_kx, 1;
    bra KX_INNER;
KX_DONE:
    // Sync before next ky to avoid RAW/WAW hazards on shared memory
    bar.sync 0;
    add.u32 r_ky, r_ky, 1;
    bra KY_LOOP;
END_KY:
    add.u32 r_kz, r_kz, 1;
    bra KZ_LOOP;
END_KZ:
    add.u32 r_ic, r_ic, 1;
    bra IC_LOOP;
END_IC:
    // Add bias if present
    setp.eq.u32 pbias0, rHasBias, 0;
    @pbias0 bra NO_BIAS;
    cvt.u64.u32 addr_b, r_oc;
    shl.b64 addr_b, addr_b, 2;
    add.u64 addr_b, addr_b, bbase;
    ld.global.f32 bval, [addr_b];
    add.f32 acc, acc, bval;
NO_BIAS:
    // Store only if within Wout
    setp.ge.u32 pstore, r_wout, rWout;
    @pstore bra END;
    // y index: (((((n*Cout + oc)*Dout + dout)*Hout + hout)*Wout + wout))
    mul.lo.u32 r_tmp3, r_n, rCout;
    add.u32    r_tmp3, r_tmp3, r_oc;
    mul.lo.u32 r_tmp3, r_tmp3, rDout;
    add.u32    r_tmp3, r_tmp3, r_dout;
    mul.lo.u32 r_tmp3, r_tmp3, rHout;
    add.u32    r_tmp3, r_tmp3, r_hout;
    mul.lo.u32 r_tmp3, r_tmp3, rWout;
    add.u32    r_tmp3, r_tmp3, r_wout;
    cvt.u64.u32 addr_y, r_tmp3;
    shl.b64 addr_y, addr_y, 2;
    add.u64 addr_y, addr_y, ybase;
    st.global.f32 [addr_y], acc;
END:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv3d_ncdhw")

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super().__init__()
        if isinstance(kernel_size, (tuple, list)):
            assert len(kernel_size) == 3 and kernel_size[0] == kernel_size[1] == kernel_size[2], "Only cubic kernels supported."
            k = int(kernel_size[0])
        else:
            k = int(kernel_size)
        assert groups == 1, "groups != 1 not supported"
        assert stride == 1, "stride != 1 not supported"
        assert dilation == 1, "dilation != 1 not supported"
        assert padding >= 0, "padding must be non-negative"
        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = k
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)
        self.groups = int(groups)
        self.has_bias = bool(bias)

        # Parameters: weight [out_channels, in_channels, K, K, K], optional bias [out_channels]
        self.weight = nn.Parameter(torch.empty(self.out_channels, self.in_channels, k, k, k))
        if self.has_bias:
            self.bias = nn.Parameter(torch.empty(self.out_channels))
        else:
            self.register_parameter("bias", None)

        # Match nn.Conv3d initialization
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.has_bias:
            fan_in = self.in_channels * (k * k * k)
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input must be on CUDA device"
        assert x.dtype == torch.float32, "Only float32 supported"
        assert x.is_contiguous(), "Input must be contiguous"
        assert self.weight.is_contiguous(), "Weight must be contiguous"
        if self.bias is not None:
            assert self.bias.is_contiguous(), "Bias must be contiguous"
        assert x.dim() == 5, "Input must be NCDHW"
        N, Cin, D, H, W = x.shape
        assert Cin == self.in_channels, "in_channels mismatch"

        K = self.kernel_size
        P = self.padding
        # For stride=1, dilation=1
        Dout = D + 2 * P - K + 1
        Hout = H + 2 * P - K + 1
        Wout = W + 2 * P - K + 1
        assert Dout > 0 and Hout > 0 and Wout > 0, "Invalid output dims"

        y = torch.empty((N, self.out_channels, Dout, Hout, Wout), device=x.device, dtype=x.dtype)

        module = _get_ptx_module()
        block_x = 128
        grid_x = (Wout + block_x - 1) // block_x
        grid_y = N * self.out_channels * Dout
        grid_z = Hout
        shared_bytes = 4 * (K + (block_x + K - 1))
        bptr = self.bias if self.bias is not None else y  # unused if has_bias=0

        module.launch(
            "conv3d_ncdhw",
            grid=(int(grid_x), int(grid_y), int(grid_z)),
            block=(block_x, 1, 1),
            arguments=[
                x,
                self.weight,
                bptr,
                y,
                u32(N),
                u32(self.in_channels),
                u32(self.out_channels),
                u32(D),
                u32(H),
                u32(W),
                u32(K),
                u32(P),
                u32(Dout),
                u32(Hout),
                u32(Wout),
                u32(1 if self.bias is not None else 0),
            ],
            shared_memory=int(shared_bytes),
            stream=torch.cuda.current_stream(x.device),
        )
        return y

prev_src:
import math
import torch
import torch.nn as nn
import torch.nn.init as init
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry conv3d_ncdhw(
    .param .u64 x_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 y_ptr,
    .param .u32 N,
    .param .u32 Cin,
    .param .u32 Cout,
    .param .u32 D,
    .param .u32 H,
    .param .u32 W,
    .param .u32 K,
    .param .u32 P,
    .param .u32 Dout,
    .param .u32 Hout,
    .param .u32 Wout,
    .param .u32 has_bias
)
{
    .reg .pred p0, p1, p2, p3, p4, p5;
    .reg .pred pin0, pin1, pall, pall1, pall2;

    .reg .b64 xbase, wbase, bbase, ybase;
    .reg .b64 addr_x, addr_w, addr_b, addr_y;

    .reg .u32 rN, rCin, rCout, rD, rH, rW, rK, rP, rDout, rHout, rWout, rHasBias;
    .reg .u32 r_tid, r_cta, r_bdim, r_tot;
    .reg .u32 r_tmp1, r_tmp2;

    .reg .u32 r_wout, r_hout, r_dout, r_oc, r_n, r_t;
    .reg .u32 r_ic, r_kz, r_ky, r_kx;

    .reg .u32 r_in_idx, r_w_idx, r_y_idx;
    .reg .u32 ru_sx, ru_sy, ru_sz;

    .reg .s32 s_x, s_y, s_z, sP, skx, sky, skz;

    .reg .f32 acc, xval, wval, bval;

    // Load pointers
    ld.param.u64 xbase, [x_ptr];
    ld.param.u64 wbase, [w_ptr];
    ld.param.u64 bbase, [b_ptr];
    ld.param.u64 ybase, [y_ptr];

    // Load sizes
    ld.param.u32 rN, [N];
    ld.param.u32 rCin, [Cin];
    ld.param.u32 rCout, [Cout];
    ld.param.u32 rD, [D];
    ld.param.u32 rH, [H];
    ld.param.u32 rW, [W];
    ld.param.u32 rK, [K];
    ld.param.u32 rP, [P];
    ld.param.u32 rDout, [Dout];
    ld.param.u32 rHout, [Hout];
    ld.param.u32 rWout, [Wout];
    ld.param.u32 rHasBias, [has_bias];

    // Compute global thread id
    mov.u32 r_tid, %tid.x;
    mov.u32 r_cta, %ctaid.x;
    mov.u32 r_bdim, %ntid.x;
    mad.lo.u32 r_tid, r_cta, r_bdim, r_tid;

    // Compute total outputs
    mov.u32 r_tot, rN;
    mul.lo.u32 r_tot, r_tot, rCout;
    mul.lo.u32 r_tot, r_tot, rDout;
    mul.lo.u32 r_tot, r_tot, rHout;
    mul.lo.u32 r_tot, r_tot, rWout;

    // Bounds check for partial block
    setp.ge.u32 p0, r_tid, r_tot;
    @p0 bra END;

    // Decode linear index -> (n, oc, dout, hout, wout)
    mov.u32 r_t, r_tid;

    rem.u32 r_wout, r_t, rWout;
    div.u32 r_t, r_t, rWout;

    rem.u32 r_hout, r_t, rHout;
    div.u32 r_t, r_t, rHout;

    rem.u32 r_dout, r_t, rDout;
    div.u32 r_t, r_t, rDout;

    rem.u32 r_oc, r_t, rCout;
    div.u32 r_n, r_t, rCout;

    // Initialize accumulator
    mov.f32 acc, 0f00000000;

    // Loop over input channels and kernel
    mov.u32 r_ic, 0;
LOOP_IC:
    setp.ge.u32 p1, r_ic, rCin;
    @p1 bra END_IC;

    mov.u32 r_kz, 0;
LOOP_KZ:
    setp.ge.u32 p2, r_kz, rK;
    @p2 bra END_KZ;

    mov.u32 r_ky, 0;
LOOP_KY:
    setp.ge.u32 p3, r_ky, rK;
    @p3 bra END_KY;

    mov.u32 r_kx, 0;
LOOP_KX:
    setp.ge.u32 p4, r_kx, rK;
    @p4 bra END_KX;

    // Compute input coords with padding
    cvt.s32.u32 s_x, r_wout;
    cvt.s32.u32 s_y, r_hout;
    cvt.s32.u32 s_z, r_dout;

    cvt.s32.u32 sP, rP;
    cvt.s32.u32 skx, r_kx;
    cvt.s32.u32 sky, r_ky;
    cvt.s32.u32 skz, r_kz;

    add.s32 s_x, s_x, skx;
    add.s32 s_y, s_y, sky;
    add.s32 s_z, s_z, skz;

    sub.s32 s_x, s_x, sP;
    sub.s32 s_y, s_y, sP;
    sub.s32 s_z, s_z, sP;

    // Bounds check: 0 <= s_* < dim
    setp.ge.s32 pin0, s_x, 0;
    setp.lt.s32 pin1, s_x, rW;
    and.pred pall1, pin0, pin1;

    setp.ge.s32 pin0, s_y, 0;
    setp.lt.s32 pin1, s_y, rH;
    and.pred pall2, pin0, pin1;

    and.pred pall1, pall1, pall2;

    setp.ge.s32 pin0, s_z, 0;
    setp.lt.s32 pin1, s_z, rD;
    and.pred pall, pall1, pin0;
    and.pred pall, pall, pin1;

    @!pall bra SKIP_ACC;

    // x index: (((((n*Cin + ic)*D + z)*H + y)*W + x))
    cvt.u32.s32 ru_sx, s_x;
    cvt.u32.s32 ru_sy, s_y;
    cvt.u32.s32 ru_sz, s_z;

    mul.lo.u32 r_tmp1, r_n, rCin;       // n*Cin
    add.u32    r_tmp1, r_tmp1, r_ic;    // + ic
    mul.lo.u32 r_tmp1, r_tmp1, rD;      // * D
    add.u32    r_tmp1, r_tmp1, ru_sz;   // + z
    mul.lo.u32 r_tmp1, r_tmp1, rH;      // * H
    add.u32    r_tmp1, r_tmp1, ru_sy;   // + y
    mul.lo.u32 r_tmp1, r_tmp1, rW;      // * W
    add.u32    r_in_idx, r_tmp1, ru_sx; // + x

