.version 8.0
.target sm_89
.address_size 64

.visible .entry conv3d_ncdhw(
    .param .u64 x_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 y_ptr,
    .param .u32 N,
    .param .u32 Cin,
    .param .u32 Cout,
    .param .u32 D,
    .param .u32 H,
    .param .u32 W,
    .param .u32 K,
    .param .u32 P,
    .param .u32 Dout,
    .param .u32 Hout,
    .param .u32 Wout,
    .param .u32 has_bias
)
{
