    mov.u32 r_tid, %tid.x;
    mov.u32 r_cta, %ctaid.x;
    mov.u32 r_bdim, %ntid.x;
    mad.lo.u32 r_tid, r_cta, r_bdim, r_tid;

    // Compute total outputs
    mov.u32 r_tot, rN;
    mul.lo.u32 r_tot, r_tot, rCout;
    mul.lo.u32 r_tot, r_tot, rDout;
    mul.lo.u32 r_tot, r_tot, rHout;
    mul.lo.u32 r_tot, r_tot, rWout;

