    mov.u32 r_t, r_tid;

    rem.u32 r_wout, r_t, rWout;
    div.u32 r_t, r_t, rWout;

    rem.u32 r_hout, r_t, rHout;
    div.u32 r_t, r_t, rHout;

    rem.u32 r_dout, r_t, rDout;
    div.u32 r_t, r_t, rDout;

    rem.u32 r_oc, r_t, rCout;
    div.u32 r_n, r_t, rCout;

