    mov.u32 r_ic, 0;
LOOP_IC:
    setp.ge.u32 p1, r_ic, rCin;
    @p1 bra END_IC;

    mov.u32 r_kz, 0;
LOOP_KZ:
    setp.ge.u32 p2, r_kz, rK;
    @p2 bra END_KZ;

    mov.u32 r_ky, 0;
LOOP_KY:
    setp.ge.u32 p3, r_ky, rK;
    @p3 bra END_KY;

