    setp.lt.s32 pin1, s_x, rW;
    and.pred pall1, pin0, pin1;

    setp.ge.s32 pin0, s_y, 0;
    setp.lt.s32 pin1, s_y, rH;
    and.pred pall2, pin0, pin1;

    and.pred pall1, pall1, pall2;

    setp.ge.s32 pin0, s_z, 0;
    setp.lt.s32 pin1, s_z, rD;
    and.pred pall, pall1, pin0;
    and.pred pall, pall, pin1;

