    mul.lo.u32 r_tmp1, r_tmp1, rD;      // * D
    add.u32    r_tmp1, r_tmp1, ru_sz;   // + z
    mul.lo.u32 r_tmp1, r_tmp1, rH;      // * H
    add.u32    r_tmp1, r_tmp1, ru_sy;   // + y
    mul.lo.u32 r_tmp1, r_tmp1, rW;      // * W
    add.u32    r_in_idx, r_tmp1, ru_sx; // + x

    cvt.u64.u32 addr_x, r_in_idx;
    shl.b64 addr_x, addr_x, 2;
    add.u64 addr_x, addr_x, xbase;

    ld.global.f32 xval, [addr_x];

    // w index: (((((oc*Cin + ic)*K + kz)*K + ky)*K + kx))
    mul.lo.u32 r_tmp2, r_oc, rCin;   // oc*Cin
    add.u32    r_tmp2, r_tmp2, r_ic; // + ic
    mul.lo.u32 r_tmp2, r_tmp2, rK;   // * K
    add.u32    r_tmp2, r_tmp2, r_kz; // + kz
    mul.lo.u32 r_tmp2, r_tmp2, rK;   // * K
    add.u32    r_tmp2, r_tmp2, r_ky; // + ky
    mul.lo.u32 r_tmp2, r_tmp2, rK;   // * K
    add.u32    r_w_idx, r_tmp2, r_kx;// + kx

    cvt.u64.u32 addr_w, r_w_idx;
    shl.b64 addr_w, addr_w, 2;
    add.u64 addr_w, addr_w, wbase;

    ld.global.f32 wval, [addr_w];

    fma.rn.f32 acc, xval, wval, acc;

SKIP_ACC:
    add.u32 r_kx, r_kx, 1;
    bra LOOP_KX;

END_KX:
    add.u32 r_ky, r_ky, 1;
    bra LOOP_KY;

END_KY:
    add.u32 r_kz, r_kz, 1;
    bra LOOP_KZ;

END_KZ:
    add.u32 r_ic, r_ic, 1;
    bra LOOP_IC;

END_IC:

    // Add bias if present
    setp.eq.u32 p5, rHasBias, 0;
    @p5 bra NO_BIAS;

    cvt.u64.u32 addr_b, r_oc;
    shl.b64 addr_b, addr_b, 2;
    add.u64 addr_b, addr_b, bbase;
    ld.global.f32 bval, [addr_b];
    add.f32 acc, acc, bval;

