    // y index: (((((n*Cout + oc)*Dout + dout)*Hout + hout)*Wout + wout))
    mul.lo.u32 r_tmp1, r_n, rCout;
    add.u32    r_tmp1, r_tmp1, r_oc;
    mul.lo.u32 r_tmp1, r_tmp1, rDout;
    add.u32    r_tmp1, r_tmp1, r_dout;
    mul.lo.u32 r_tmp1, r_tmp1, rHout;
    add.u32    r_tmp1, r_tmp1, r_hout;
    mul.lo.u32 r_tmp1, r_tmp1, rWout;
    add.u32    r_y_idx, r_tmp1, r_wout;

    cvt.u64.u32 addr_y, r_y_idx;
    shl.b64 addr_y, addr_y, 2;
    add.u64 addr_y, addr_y, ybase;

    st.global.f32 [addr_y], acc;

END:
    ret;
}
